import React, { useState } from 'react';

function TextInputDisplay() {
  const [code, setCode] = useState('');
  const [tokens, setTokens] = useState([]);
  const [arbol, setArbol] = useState('');
  const [errores, setErrores] = useState([]);
  const [acciones, setAcciones] = useState([]);

  const analizarCodigo = async () => {
    try {
      const response = await fetch('http://localhost:8081/api/analyze', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ code }),
      });

      const data = await response.json();

      setTokens(data.tokens || []);
      setArbol(data.arbol || '');
      setErrores(data.errores || []);
      setAcciones(data.acciones || []);
    } catch (error) {
      console.error('Error al analizar el código:', error);
    }
  };

  return (
    <div className="p-4 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">Analizador de Código</h1>

      <textarea
        className="w-full h-40 p-2 border rounded mb-4"
        placeholder="Escribe tu código aquí..."
        value={code}
        onChange={(e) => setCode(e.target.value)}
      />

      <button
        className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700"
        onClick={analizarCodigo}
      >
        Analizar
      </button>

      {errores.length > 0 && (
        <div className="mt-6 bg-red-100 border border-red-400 text-red-700 p-4 rounded">
          <h2 className="font-semibold mb-2">Errores:</h2>
          <ul>
            {errores.map((error, index) => (
              <li key={index}>
                Línea {error.linea}, Columna {error.columna}: {error.mensaje}
              </li>
            ))}
          </ul>
        </div>
      )}

      {tokens.length > 0 && (
        <div className="mt-6">
          <h2 className="font-semibold text-lg mb-2">Tokens:</h2>
          <ul className="list-disc pl-5">
            {tokens.map((token, index) => (
              <li key={index}>
                {token.tipo} → "{token.valor}" (Línea {token.linea}, Columna {token.columna})
              </li>
            ))}
          </ul>
        </div>
      )}

      {acciones.length > 0 && (
        <div className="mt-6">
          <h2 className="font-semibold text-lg mb-2">Acciones:</h2>
          <ul className="list-disc pl-5 text-green-700">
            {acciones.map((accion, index) => (
              <li key={index}>{accion}</li>
            ))}
          </ul>
        </div>
      )}

      {arbol && (
        <div className="mt-6">
          <h2 className="font-semibold text-lg mb-2">Árbol de análisis:</h2>
          <pre className="bg-gray-100 p-2 rounded overflow-auto">{arbol}</pre>
        </div>
      )}
    </div>
  );
}

export default TextInputDisplay;
